import{_ as r,o as a,c as n,a2 as t}from"./chunks/framework.CvydjLy7.js";const f=JSON.parse('{"title":"缓存、校验与外部服务调用","description":"","frontmatter":{"title":"缓存、校验与外部服务调用"},"headers":[{"level":2,"title":"本篇小节","slug":"本篇小节","link":"#本篇小节","children":[]}],"relativePath":"ch07/index.md","filePath":"ch07/index.md","lastUpdated":1789497795000}'),i={name:"ch07/index.md"};function l(o,e,c,s,h,d){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="缓存、校验与外部服务调用" tabindex="-1">缓存、校验与外部服务调用 <a class="header-anchor" href="#缓存、校验与外部服务调用" aria-label="Permalink to &quot;缓存、校验与外部服务调用&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本篇对应官方章节</p><p><a href="https://docs.spring.io/spring-boot/reference/io/caching.html" target="_blank" rel="noreferrer">缓存</a> · <a href="https://docs.spring.io/spring-boot/reference/io/validation.html" target="_blank" rel="noreferrer">校验</a> · <a href="https://docs.spring.io/spring-boot/reference/io/rest-client.html" target="_blank" rel="noreferrer">REST Client</a> · <a href="https://docs.spring.io/spring-boot/reference/io/email.html" target="_blank" rel="noreferrer">邮件</a> · <a href="https://docs.spring.io/spring-boot/reference/io/quartz.html" target="_blank" rel="noreferrer">Quartz 调度</a> · <a href="https://docs.spring.io/spring-boot/reference/features/task-execution-and-scheduling.html" target="_blank" rel="noreferrer">任务执行与调度</a></p></div><blockquote><p>第 6 篇把数据落盘了，接口也稳了。这一篇处理的是“应用与外部世界打交道”的那一层：怎么让热点查询不要每次都打数据库（缓存），怎么保证进来的数据是干净的（校验），怎么可靠地调用别人的接口（REST Client），以及怎么按时间表自己干活（定时任务）。</p><p>这一篇里有一个特别值得留意的点：<strong>缓存和定时任务都不会让程序报错</strong>。它们失效的时候是静默的——你改了数据，用户看到的还是旧值；你写了预热任务，它压根没执行。这类问题的排查成本远高于一个直接抛出来的异常，所以本篇的实测部分会格外关注“怎么证明它真的生效了”。</p></blockquote><h2 id="本篇小节" tabindex="-1">本篇小节 <a class="header-anchor" href="#本篇小节" aria-label="Permalink to &quot;本篇小节&quot;">​</a></h2><ul><li><a href="/backend-engineering-course/ch07/01.html">一、官方 IO 一章覆盖了什么</a></li><li><a href="/backend-engineering-course/ch07/02.html">二、缓存：把热点查询挡在数据库前面</a></li><li><a href="/backend-engineering-course/ch07/03.html">三、参数校验：从 DTO 到配置项</a></li><li><a href="/backend-engineering-course/ch07/04.html">四、调用外部服务：RestClient</a></li><li><a href="/backend-engineering-course/ch07/05.html">五、配置里的 Duration：一个不会报错的坑</a></li><li><a href="/backend-engineering-course/ch07/06.html">六、定时任务</a></li><li><a href="/backend-engineering-course/ch07/07.html">七、发送邮件</a></li><li><a href="/backend-engineering-course/ch07/08.html">八、Quartz：需要持久化的定时任务</a></li><li><a href="/backend-engineering-course/ch07/09.html">九、常见问题速查表</a></li><li><a href="/backend-engineering-course/ch07/10.html">附：本篇涉及的官方章节</a></li></ul>',5)])])}const p=r(i,[["render",l]]);export{f as __pageData,p as default};
